package net.civeira.phylax.features.access.consentpurpose.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class TitleVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property title of consent purpose ")
  void test_title_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> TitleVO.tryFrom(null));
    Assertions.assertEquals("one", TitleVO.from("one").getTitle());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> TitleVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", TitleVO.from("one").toString());
  }
}
